mapper.select:
SELECT COUNT(*)
  FROM T_ATM
 WHERE TERM_GROUP_ID = #{termGroupId,jdbcType=CHAR}
   AND TERM_ID       = #{termId,jdbcType=VARCHAR}

SELECT TRIM(RECV_MACHINE_SNO)
  FROM T_ATM
 WHERE TERM_GROUP_ID = #{termGroupId,jdbcType=CHAR}
   AND TERM_ID       = #{termId,jdbcType=VARCHAR}

mapper.update:
UPDATE T_ATM
   SET ATM_STATUS       = #{atmStatus,jdbcType=CHAR}
      ,ASSET_FLAG       = #{assetFlag,jdbcType=CHAR}
      ,ATM_CO_CD        = #{atmCoCd,jdbcType=CHAR}
      ,MODEL_CD         = #{modelCd,jdbcType=CHAR}
      ,RECV_ATM_IP      = #{recvAtmIp,jdbcType=CHAR}
      ,ATM_IP           = #{atmIp,jdbcType=CHAR}
      ,ASSET_SNO        = #{assetSno,jdbcType=VARCHAR}
      ,RECV_MACHINE_SNO = #{recvMachineSno,jdbcType=VARCHAR}
      ,APP_VERSION      = #{appVersion,jdbcType=VARCHAR}
      ,STATUS_FLAG      = #{statusFlag,jdbcType=CHAR}
      ,TRAN_FLAG        = #{tranFlag,jdbcType=CHAR}
      ,PROCESSOR_TYPE   = #{processorType,jdbcType=CHAR}
      ,REMOTE_FLAG      = #{remoteFlag,jdbcType=CHAR}
      ,OWNER_CD         = #{ownerCd,jdbcType=CHAR}
      ,PROTOCOL_TYPE    = #{protocolType,jdbcType=CHAR}
 WHERE TERM_GROUP_ID    = #{termGroupId,jdbcType=CHAR}
   AND TERM_ID          = #{termId,jdbcType=VARCHAR}

UPDATE T_ATM
   SET BRANCH_CD     = #{branchCd,jdbcType=VARCHAR}
 WHERE TERM_GROUP_ID = #{termGroupId,jdbcType=CHAR}
   AND TERM_ID       = #{termId,jdbcType=VARCHAR}

UPDATE T_ATM
   SET BOOTH_TYPE_CD = #{boothTypeCd,jdbcType=CHAR}
 WHERE TERM_GROUP_ID = #{termGroupId,jdbcType=CHAR}
   AND TERM_ID       = #{termId,jdbcType=VARCHAR}
